## Layer 2: Inventory Reservation Engine
This layer handles concurrency locks to prevent race conditions during stock depletion and updates the inventory levels.

```csharp
// InventoryReservationEngine.cs
using System;
using System.Threading;
using System.Threading.Tasks;

namespace OrderProcessingApi.Inventory
{
    public interface IInventoryReservationEngine
    {
        Task ReserveInventory(Order order);
    }

    public class InventoryReservationEngine : IInventoryReservationEngine
    {
        private readonly IInventoryRepository _inventoryRepository;

        public InventoryReservationEngine(IInventoryRepository inventoryRepository)
        {
            _inventoryRepository = inventoryRepository;
        }

        public async Task ReserveInventory(Order order)
        {
            // Acquire concurrency lock
            using var lockHandle = await AcquireLock(order.ProductId);

            try
            {
                // Check if the product is in stock
                if (await _inventoryRepository.GetQuantity(order.ProductId) >= order.Quantity)
                {
                    // Reserve the product
                    await _inventoryRepository.ReserveProduct(order.ProductId, order.Quantity);
                }
                else
                {
                    throw new InvalidOperationException("Product is out of stock");
                }
            }
            finally
            {
                // Release concurrency lock
                ReleaseLock(order.ProductId, lockHandle);
            }
        }

        private async Task<LockHandle> AcquireLock(int productId)
        {
