## Layer 3: Payment Gateway Integration Subsystem
This layer implements circuit breaker patterns for third-party transaction timeouts and handles payment processing.

```csharp
// PaymentGateway.cs
using System;
using System.Threading.Tasks;

namespace OrderProcessingApi.Payment
{
    public interface IPaymentGateway
    {
        Task ProcessPayment(Order order);
    }

    public class PaymentGateway : IPaymentGateway
    {
        private readonly IPaymentGatewayClient _paymentGatewayClient;
        private readonly ICircuitBreaker _circuitBreaker;

        public PaymentGateway(IPaymentGatewayClient paymentGatewayClient, ICircuitBreaker circuitBreaker)
        {
            _paymentGatewayClient = paymentGatewayClient;
            _circuitBreaker = circuitBreaker;
        }

        public async Task ProcessPayment(Order order)
        {
            // Use the circuit breaker to prevent cascading failures
            await _circuitBreaker.Execute(() => _paymentGatewayClient.ProcessPayment(order));
        }
    }
}
```

